fun removeTeam(teams: MutableList<Int>, team: Int): List<Int> {
    teams.remove(team)
    return teams
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testRemoveMiddle() {
        val result = removeTeam(mutableListOf(4215, 1234, 5678), 1234)
        Assert.assertEquals(listOf(4215, 5678), result)
    }

    @Test
    fun testRemoveFirst() {
        val result = removeTeam(mutableListOf(4215, 1234), 4215)
        Assert.assertEquals(listOf(1234), result)
    }

    @Test
    fun testSizeDecreases() {
        val result = removeTeam(mutableListOf(100, 200, 300), 200)
        Assert.assertEquals(2, result.size)
    }
}
